import{_ as o,C as s,o as a,c as r,j as t,a as i,E as h,a6 as c}from"./chunks/framework.CCKCzdWs.js";const f=JSON.parse('{"title":"Extension connection","description":"Connect Piwi Picker to your Piwi instance in one step, and keep the URL patterns that tell it which project a page belongs to on the instance, shared by your team.","frontmatter":{"title":"Extension connection","description":"Connect Piwi Picker to your Piwi instance in one step, and keep the URL patterns that tell it which project a page belongs to on the instance, shared by your team.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/extension-connection.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/extension-connection.html"}],["meta",{"property":"og:title","content":"Extension connection | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Connect Piwi Picker to your Piwi instance in one step, and keep the URL patterns that tell it which project a page belongs to on the instance, shared by your team."}]]},"headers":[],"relativePath":"features/extension-connection.md","filePath":"features/extension-connection.md","lastUpdated":1794933930000}'),d={name:"features/extension-connection.md"};function p(l,e,g,u,w,m){const n=s("Needs");return a(),r("div",null,[e[0]||(e[0]=t("h1",{id:"extension-connection",tabindex:"-1"},[i("Extension connection "),t("a",{class:"header-anchor",href:"#extension-connection","aria-label":'Permalink to "Extension connection"'},"​")],-1)),h(n,{extension:""}),e[1]||(e[1]=c('<p><a href="./extension.html">Piwi Picker</a> works on its own. Connected to your Piwi instance, it also matches a recording against your project&#39;s <a href="./test-functions.html">test functions</a> and shows <a href="./tested-elements.html">Tested elements</a>. Connecting takes one click, and the URL patterns that say which project a page belongs to live on the instance, so a team sets them once. Pairing with the desktop app, and what each connection sends, are here too.</p><h2 id="connect-in-one-step" tabindex="-1">Connect in one step <a class="header-anchor" href="#connect-in-one-step" aria-label="Permalink to &quot;Connect in one step&quot;">​</a></h2><ol><li>In Piwi Picker&#39;s settings (the gear button in its popup), type your instance&#39;s address.</li><li>Click <strong>Connect</strong>. The browser asks to let Piwi Picker reach that one address; allow it.</li><li>A tab opens on your instance. Sign in if asked, with a password or your usual sign-in provider: you come back to the same page. It names the connecting browser (&quot;Piwi Picker in Chrome on Windows&quot;) and shows a code.</li><li>Check that the settings page shows the same code, tick <strong>My Piwi Picker shows this same code</strong>, then click <strong>Allow</strong>. The link carries the code, so anyone could send you one: if you did not just click <strong>Connect</strong>, deny.</li></ol><p>The tab closes, the settings say <strong>Connected as</strong> your name, and the instance&#39;s URL patterns show under <strong>From your Piwi instance</strong>.</p><p>Allowing creates an API key for your account, named after the browser, with your instance role and project roles. It is listed under <strong>Settings → Account → <a href="/features/run-on-my-machine.html#connected-apps">Connected apps</a></strong>, where you revoke it; the browser is then disconnected at its next request. <strong>Deny</strong>, or ten minutes without an answer, creates nothing.</p><p>With <a href="/operate/authentication.html">authentication</a> off, <strong>Allow</strong> only confirms the connection: there is no account to own a key, and none is needed.</p><h3 id="is-the-connection-working" tabindex="-1">Is the connection working? <a class="header-anchor" href="#is-the-connection-working" aria-label="Permalink to &quot;Is the connection working?&quot;">​</a></h3><p>The popup says how the last request to your instance went, under <strong>Active project</strong> (&quot;Connected to piwi.example.com, checked 5 minutes ago&quot;), or since when nothing answers, the key is refused or the instance answers with errors, with a link to the settings, which show the same beside the address. A revoked key thus shows at the next request, before a tool fails: click <strong>Connect</strong> again.</p><h3 id="use-an-api-key-instead" tabindex="-1">Use an API key instead <a class="header-anchor" href="#use-an-api-key-instead" aria-label="Permalink to &quot;Use an API key instead&quot;">​</a></h3><p>Under <strong>Use an API key instead</strong>, paste a key created in your account&#39;s <a href="/operate/api-keys.html">API key settings</a> and click <strong>Save and test</strong>. An instance older than the one-step connection needs this.</p><h3 id="the-desktop-app-as-your-instance" tabindex="-1">The desktop app as your instance <a class="header-anchor" href="#the-desktop-app-as-your-instance" aria-label="Permalink to &quot;The desktop app as your instance&quot;">​</a></h3><p>Once the <a href="./desktop.html">desktop app</a> is <a href="#pair-with-the-desktop-app">paired</a> and no instance is connected, <strong>Use the desktop app as your instance</strong> fills in the app&#39;s address and token as the API key, checks them and connects: the app&#39;s instance answers only requests carrying that token. If the app, installed again, refuses it, paste the one from its <strong>Pair with Piwi Picker</strong> card, or pair again. Typed by hand, the address must use <code>127.0.0.1</code>, since <code>localhost</code> may reach another program.</p><h2 id="pair-with-the-desktop-app" tabindex="-1">Pair with the desktop app <a class="header-anchor" href="#pair-with-the-desktop-app" aria-label="Permalink to &quot;Pair with the desktop app&quot;">​</a></h2><p>Pairing lets Piwi Picker <a href="./replay-a-bug-report.html#running-it-with-playwright">run a report with Playwright</a> in the app, follow its runs in the <a href="./runs-window.html">Runs window</a> and use it as its instance. Under <strong>Desktop app</strong> in the settings, click <strong>Pair</strong>, then <strong>Allow</strong> in the app&#39;s window, which shows the same code. <strong>Pair by hand</strong> takes the address and token shown in the app&#39;s <strong>Settings → Desktop app</strong>, under <strong>Pair with Piwi Picker</strong> (<code>http://127.0.0.1:3000</code> by default). While an instance is connected and no app is paired, the settings point here.</p><p>The token goes out only after the program at that address proves it holds it, before every request: another program on the app&#39;s port receives nothing, after <strong>Unpair</strong> too. <strong>Disconnect</strong> leaves the shared address granted to the app, and <strong>Unpair</strong> to the instance or the editor.</p><h2 id="url-patterns" tabindex="-1">URL patterns <a class="header-anchor" href="#url-patterns" aria-label="Permalink to &quot;URL patterns&quot;">​</a></h2><p>A URL pattern is a glob over a page&#39;s whole address: <code>*</code> matches within one part of the path, <code>**</code> across parts. So <code>https://staging.shop.example/**</code> covers every page of that site, and <code>https://shop.example/admin/*</code> the pages one level under <code>/admin</code>. A pattern starts with <code>http://</code>, <code>https://</code> or a wildcard.</p><p>Each project keeps its own list in the <strong>Browser extension</strong> section of its <strong>Settings</strong> tab. A pattern can name:</p><ul><li>an <strong>environment</strong>, a label shown beside the project in Piwi Picker (<code>staging</code>, <code>production</code>);</li><li>a <strong>branch</strong>, the one deployed at those addresses, whose tests <a href="./tested-elements.html">Tested elements</a> shows;</li><li>a <strong>path prefix</strong>, the part of the path your site serves its pages under and the tests did not: <code>/app</code> when the site serves <code>/app/checkout</code> and the tests ran at <code>/checkout</code>. Piwi Picker removes it before comparing the page with the <a href="./tested-elements.html#this-page">pages the tests ran on</a>, whole parts only (<code>/application</code> keeps its path), and a bug report sent from the site keys its page without it. It is a plain path of at most four parts, with no query, hash or wildcard;</li><li>a <strong>tests&#39; path prefix</strong>, the reverse: the part of the path the tests ran the pages under and the site does not, <code>/app</code> when the tests ran <code>/app/checkout</code> and the site serves <code>/checkout</code>. Piwi Picker puts it in front of the page&#39;s path; the site&#39;s root becomes <code>/app</code>. With both set, the one replaces the other (<code>/app</code> on the site, <code>/v2</code> in the tests), and a page outside the path prefix is left as it is.</li></ul><p>The editor suggests one pattern per site your suite already visited, grouped by the environment each run was reported with (the <a href="/guide/reporter.html">reporter</a>&#39;s <code>environment</code> option or <code>PIWI_ENVIRONMENT</code>), from the newest few runs of every environment, so a nightly production suite shows beside a staging one. A run&#39;s site is its <code>baseURL</code>; for a run with none, the full addresses its tests opened with <code>page.goto</code> and the pages it loaded (its <code>document</code> requests), then the <a href="./scenario-gaps.html">Test Map</a>&#39;s pages and the absolute pages its locators ran on. A run merged from blob reports (<code>npx playwright merge-reports</code>, or a blob report imported in the dashboard) has no <code>baseURL</code>, which Playwright leaves out of them, so its sites come from the page loads the <a href="/guide/capture-fixtures.html">capture fixtures</a> record for every test, or the trace of a failed test. <strong>Add</strong> puts a suggestion in the list with its environment, <strong>Add all</strong> every suggestion of that environment; <strong>Save patterns</strong> stores them. When there is nothing to suggest, the editor says why: every site already has a pattern, or no recent run recorded a <code>baseURL</code>, opened a full address or kept the network requests of a page it loaded. Editing the list takes the Project admin role.</p><h3 id="which-project-applies" tabindex="-1">Which project applies <a class="header-anchor" href="#which-project-applies" aria-label="Permalink to &quot;Which project applies&quot;">​</a></h3><p>Piwi Picker reads the patterns of every project you can see when it connects and each time its settings open, and keeps a copy, so a page&#39;s project is known with the instance out of reach. For a page it decides in this order:</p><ol><li>the project chosen in the popup&#39;s <strong>Active project</strong> on that site, for the rest of the browser session or until you disconnect;</li><li>the patterns under <strong>This browser only</strong>, the first that matches;</li><li>the instance&#39;s patterns, by project, in each project&#39;s order, the first that matches.</li></ol><p>A pattern kept in the browser is an override for that browser alone, and the settings mark where each comes from. <strong>Disconnect</strong> sets the patterns of this browser aside: connecting to the same instance again brings them back, and connecting to another drops them, since they name the first one&#39;s projects. A connection left unfinished leaves them aside for the next one.</p><h3 id="add-a-site" tabindex="-1">Add a site <a class="header-anchor" href="#add-a-site" aria-label="Permalink to &quot;Add a site&quot;">​</a></h3><p>When the tab matches no pattern, the popup offers <strong>Add this site</strong>, which opens the settings with <code>https://&lt;site&gt;/**</code> filled in: choose a project and click <strong>Add to Piwi</strong>, or <strong>Keep in this browser only</strong>. Adding to the instance takes a role that edits the project; without one, the settings say so and keep the second choice.</p><h2 id="what-is-sent" tabindex="-1">What is sent <a class="header-anchor" href="#what-is-sent" aria-label="Permalink to &quot;What is sent&quot;">​</a></h2><p>Connecting, and pairing with the desktop app, send the browser&#39;s and operating system&#39;s names, nothing else about the machine. It then downloads the projects, the URL patterns, each mapped project&#39;s function catalog, locator index and bug reports, and the runs in progress. It sends the instance nothing else but these, each on your click: a site&#39;s pattern (<strong>Add this site</strong>), a bug report after the <strong>Send to Piwi…</strong> preview (<a href="./bug-reports.html#sending-a-report">sending one</a>), and a replay&#39;s answer (<strong>Share result…</strong>). A recording goes only to a paired editor (<strong>Send to editor</strong>), and steps only to the paired desktop app (<strong>Run with Playwright…</strong>). Only the settings page and the background worker make requests, never a page&#39;s script.</p><p>While connected, Piwi Picker also marks your instance&#39;s pages in this browser: a script sets <code>data-piwi-picker</code>, with the extension&#39;s version, on each page. The dashboard then stops suggesting Piwi Picker, as it does once you click <strong>Don&#39;t show again</strong> on its hint. The script reads nothing from the page and sends nothing, and <strong>Disconnect</strong> stops it.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./extension.html">Browser extension</a>: everything Piwi Picker does, with or without a connection</li><li><a href="/operate/api-keys.html">API keys</a>: create, list and revoke keys; Piwi Picker&#39;s is under Connected apps</li><li><a href="./tested-elements.html">Tested elements</a>: what a connection shows on the page</li><li><a href="/operate/project-access.html">Access, roles and groups</a>: which projects, and so which patterns, a user sees</li></ul>',31))])}const y=o(d,[["render",p]]);export{f as __pageData,y as default};
